CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_read_own ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY bookings_admin_read ON public.bookings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.destination_prices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), attraction_slug text NOT NULL, activity text NOT NULL, visitor_category text NOT NULL, adult_price numeric NOT NULL CHECK(adult_price>=0), child_price numeric CHECK(child_price>=0), child_age_max integer CHECK(child_age_max BETWEEN 0 AND 17), currency text NOT NULL CHECK(currency IN ('USD','RWF')), source_url text NOT NULL CHECK(source_url ~ '^https://'), verified_on date NOT NULL, notes text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.destination_prices TO anon,authenticated; GRANT INSERT,UPDATE ON public.destination_prices TO authenticated; GRANT ALL ON public.destination_prices TO service_role;
ALTER TABLE public.destination_prices ENABLE ROW LEVEL SECURITY;
CREATE POLICY price_public_read ON public.destination_prices FOR SELECT TO anon,authenticated USING(active);
CREATE POLICY price_admin_read ON public.destination_prices FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE POLICY price_admin_insert ON public.destination_prices FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE POLICY price_admin_update ON public.destination_prices FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.bookings ADD COLUMN children integer NOT NULL DEFAULT 0 CHECK(children BETWEEN 0 AND 19), ADD COLUMN visitor_category text NOT NULL DEFAULT '', ADD COLUMN price_id uuid REFERENCES public.destination_prices(id), ADD COLUMN total_price numeric, ADD COLUMN currency text, ADD COLUMN price_source text, ADD COLUMN price_verified_on date;
CREATE FUNCTION public.calculate_booking_price() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.destination_prices; BEGIN IF NEW.children>=NEW.visitors THEN RAISE EXCEPTION 'At least one adult is required'; END IF; NEW.total_price:=NULL; NEW.currency:=NULL; NEW.price_source:=NULL; NEW.price_verified_on:=NULL; IF NEW.price_id IS NOT NULL THEN SELECT * INTO p FROM public.destination_prices WHERE id=NEW.price_id AND active AND attraction_slug=NEW.attraction_slug AND activity=NEW.experience AND visitor_category=NEW.visitor_category; IF NOT FOUND THEN RAISE EXCEPTION 'Price does not match booking'; END IF; IF NEW.children>0 AND p.child_price IS NULL THEN RAISE EXCEPTION 'Child price is not verified'; END IF; NEW.total_price:=(NEW.visitors-NEW.children)*p.adult_price+NEW.children*coalesce(p.child_price,0); NEW.currency:=p.currency; NEW.price_source:=p.source_url; NEW.price_verified_on:=p.verified_on; END IF; RETURN NEW; END; $$;
CREATE TRIGGER calculate_booking_price BEFORE INSERT ON public.bookings FOR EACH ROW EXECUTE FUNCTION public.calculate_booking_price();
CREATE TABLE public.booking_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES public.bookings(id), actor_id uuid NOT NULL, previous_status text NOT NULL, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.booking_events TO authenticated; GRANT ALL ON public.booking_events TO service_role;
ALTER TABLE public.booking_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY booking_events_read ON public.booking_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR EXISTS(SELECT 1 FROM public.bookings WHERE id=booking_id AND user_id=auth.uid()));
CREATE FUNCTION public.cancel_pending_booking(_booking_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE changed uuid; BEGIN UPDATE public.bookings SET status='Cancelled' WHERE id=_booking_id AND user_id=auth.uid() AND status='Pending' RETURNING id INTO changed; IF changed IS NULL THEN RAISE EXCEPTION 'Only your pending bookings can be cancelled'; END IF; INSERT INTO public.booking_events(booking_id,actor_id,previous_status,status) VALUES(changed,auth.uid(),'Pending','Cancelled'); RETURN changed; END; $$;
REVOKE ALL ON FUNCTION public.cancel_pending_booking(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cancel_pending_booking(uuid) TO authenticated;
CREATE FUNCTION public.admin_booking_status(_booking_id uuid,_status text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE old_status text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF _status NOT IN ('Approved','Rejected') THEN RAISE EXCEPTION 'Choose Approved or Rejected'; END IF; SELECT status INTO old_status FROM public.bookings WHERE id=_booking_id FOR UPDATE; IF old_status IS DISTINCT FROM 'Pending' THEN RAISE EXCEPTION 'Only pending bookings can be reviewed'; END IF; UPDATE public.bookings SET status=_status WHERE id=_booking_id; INSERT INTO public.booking_events(booking_id,actor_id,previous_status,status) VALUES(_booking_id,auth.uid(),old_status,_status); RETURN _booking_id; END; $$;
REVOKE ALL ON FUNCTION public.admin_booking_status(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.admin_booking_status(uuid,text) TO authenticated;
CREATE TABLE public.itineraries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id), preferences jsonb NOT NULL, plan jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.itineraries TO authenticated; GRANT ALL ON public.itineraries TO service_role;
ALTER TABLE public.itineraries ENABLE ROW LEVEL SECURITY;
CREATE POLICY itinerary_read_own ON public.itineraries FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY itinerary_insert_own ON public.itineraries FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY itinerary_delete_own ON public.itineraries FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.ai_feature_state(feature text PRIMARY KEY, blocked boolean NOT NULL DEFAULT false, reason text NOT NULL DEFAULT '');
GRANT SELECT ON public.ai_feature_state TO authenticated; GRANT ALL ON public.ai_feature_state TO service_role;
ALTER TABLE public.ai_feature_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY ai_state_read ON public.ai_feature_state FOR SELECT TO authenticated USING(true);